package com.nuvio.tv.ui.screens.search

// TMDB daily TV-network ID export (11_03_2026); names and IDs only.
// Source: https://developer.themoviedb.org/docs/daily-id-exports
internal data class TvNetworkMatch(val id: Int, val name: String)

internal object TvNetworkDirectory {
    private val entries by lazy {
        chunks.asSequence().flatMap { it.lineSequence() }.mapNotNull { line ->
            val separator = line.indexOf('\t')
            if (separator <= 0) null else {
                val id = line.substring(0, separator).toIntOrNull()
                val name = line.substring(separator + 1)
                if (id == null || name.isBlank()) null else TvNetworkMatch(id, name)
            }
        }.toList()
    }
    private fun normalized(value: String): String = value.lowercase().map { c ->
        when (c) {
            'á', 'à', 'â', 'ã', 'ä' -> 'a'
            'é', 'è', 'ê', 'ë' -> 'e'
            'í', 'ì', 'î', 'ï' -> 'i'
            'ó', 'ò', 'ô', 'õ', 'ö' -> 'o'
            'ú', 'ù', 'û', 'ü' -> 'u'
            'ç' -> 'c'
            else -> c
        }
    }.joinToString("")

    fun search(query: String, limit: Int = 12): List<TvNetworkMatch> {
        val term = normalized(query.trim())
        if (term.length < 2 || limit <= 0) return emptyList()
        return entries.asSequence().filter { normalized(it.name).contains(term) }
            .sortedBy { if (normalized(it.name).startsWith(term)) 0 else 1 }
            .take(limit).toList()
    }
